{"tool": "writeProjectFile", "params": {"content": "import { createHmac, timingSafeEqual } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

// Constants
const NONCE_CACHE_PATH = path.join(process.cwd(), 'data', '.bridge-nonce-cache');
const NONCE_WINDOW_MS = 5 * 60 * 1000;

export type HelloEnvelope = {
  deviceId: string;
  ts: number;
  nonce: string;
  payload: unknown;
  sig: string;
};

export function canonicalize(obj: unknown): string {
  const sortObject = (o: any): any => {
    if (o === null || typeof o !== 'object' || Array.isArray(o)) return o;
    return Object.keys(o).sort().reduce((acc, key) => {
      acc[key] = sortObject(o[key]);
      return acc;
    }, {} as any);
  };
  return JSON.stringify(sortObject(obj));
}

export async function isFreshNonce(nonce: string, ts: number): Promise<boolean> {
  const now = Date.now();
  if (Math.abs(now - ts) > NONCE_WINDOW_MS) return false;

  try {
    let cache: string[] = [];
    try {
      const content = await readFile(NONCE_CACHE_PATH, 'utf-8');
      cache = JSON.parse(content);
    } catch { /* file doesn't exist yet */ }

    if (cache.includes(nonce)) return false;

    cache.push(nonce);
    // Keep cache size bounded
    if (cache.length > 1000) cache.shift();

    await writeFile(NONCE_CACHE_PATH, JSON.stringify(cache));
    return true;
  } catch { return false; }
}

export function verifyHelloSignature(envelope: HelloEnvelope, secret: string): { ok: true; sessionId: string } | { ok: false; reason: string } {
  if (typeof secret !== 'string' || Buffer.from(secret).length < 32) {
    return { ok: false, reason: 'Secret too short or invalid' };
  }

  const { sig, ...data } = envelope;
  const hmac = createHmac('sha256', secret);
  hmac.update(canonicalize(data));
  const expectedSig = hmac.digest('hex');

  if (timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) {
    return { ok: true, sessionId: `sess_${envelope.deviceId}_${envelope.ts}` };
  }

  return { ok: false, reason: 'Invalid signature' };
}", "path": "src/lib/phone/hello-verify.ts"}}
